export function lookupUniversityMeta(name: string, fallbackUrl?: string, countryTuition?: string): UniversityMeta {
  if (universityDictionary[name]) {
    return universityDictionary[name];
  }

  const clean = name.toLowerCase().trim();
  for (const [k, v] of Object.entries(universityDictionary)) {
    const kClean = k.toLowerCase().trim();
    if (clean === kClean || clean.includes(kClean) || kClean.includes(clean.split("(")[0].split(",")[0].trim())) {
      return v;
    }
  }

  let domain = "";
  if (fallbackUrl) {
    try {
      domain = new URL(fallbackUrl).hostname;
    } catch {}
  }

  return {
    websiteUrl: fallbackUrl || "",
    logoUrl: domain ? `https://www.google.com/s2/favicons?domain=${domain}&sz=128` : "",
    tuitionFeeRange: countryTuition || "Contact for Tuition Fees",
    requirements: "Academic GPA 65%+ / 2.8+; IELTS 6.0 - 6.5 or equivalent",
  };
}
